def sanitize(name):
    return re.sub(r'[^a-zA-Z0-9_\-\s]', '', name).strip().replace(' ', '_')

items = []
seen_names = set()

blocks = re.findall(r'(<li[\s\S]*?</li>)', html_content)
for block in blocks:
    name_match = re.search(r'data-qa="item-name">([^<]+)</span>', block)
    if not name_match:
        name_match = re.search(r'class="popular-item-style_name__T__oA"[^>]*>([^<]+)</span>', block)
    
    img_match = re.search(r'<img [^>]*src="([^"]+)"', block)
    
    if name_match and img_match:
        dish_name = name_match.group(1).strip()
        raw_url = img_match.group(1)
        if not raw_url.startswith('http'):
            continue
        
        if dish_name in seen_names:
            continue
        seen_names.add(dish_name)
        
        ext = '.png' if '.png' in raw_url else '.jpg'
        filename = f"dish_{sanitize(dish_name)}{ext}"
        
        hd_url = re.sub(r'c_thumb,w_\d+/', 'c_limit,w_800/', raw_url)
        items.append((filename, hd_url, raw_url))

print(f"Total unique dish images found in snippet: {len(items)}")

def download(url, dest):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req) as resp, open(dest, 'wb') as f:
        f.write(resp.read())

for fname, hd_url, raw_url in items:
    dest = os.path.join(output_dir, fname)
    print(f"Downloading {fname}...")
    try:
        download(hd_url, dest)
        print(f"  Saved HD version: {fname}")
    except Exception as e:
        print(f"  HD download failed ({e}), falling back to original URL...")
        try:
            download(raw_url, dest)
            print(f"  Saved original version: {fname}")
        except Exception as e2:
            print(f"  Failed completely for {fname}: {e2}")

print("All downloads completed!")
